def transform(grid):
    rows = len(grid)
    cols = len(grid[0])

    from collections import Counter
    counts = Counter()
    for row in grid:
        for c in row:
            counts[c] += 1

    sorted_colors = sorted(counts.keys(), key=lambda x: -counts[x])
    interior_color = sorted_colors[0]
    enclosure_color = sorted_colors[1] if len(sorted_colors) > 1 else None

    if enclosure_color is None:
        return [row[:] for row in grid]

    result = [row[:] for row in grid]

    for i in range(rows):
        for j in range(cols):
            c = grid[i][j]

            if c != interior_color:
                continue

            has_up = any(grid[k][j] == enclosure_color for k in range(i + 1, rows))
            has_down = any(grid[k][j] == enclosure_color for k in range(i - 1, -1, -1))
            has_left = any(grid[i][k] == enclosure_color for k in range(j - 1, -1, -1))
            has_right = any(grid[i][k] == enclosure_color for k in range(j + 1, cols))

            if has_up and has_down and has_left and has_right:
                result[i][j] = 4

    return result

